import json, subprocess
from pathlib import Path
ANCHOR = "b451b96"
ACTIVE_PHASE_FILE = ".agent/feature_list_013.json"
OWN_ID = "096"
tracked = subprocess.run(["git", "ls-files", ".agent/feature_list*.json"], capture_output=True, text=True, check=True).stdout.split()
for p in tracked:
    if p == ACTIVE_PHASE_FILE:
        continue
    rc = subprocess.run(["git", "diff", "--quiet", ANCHOR, "--", p]).returncode
    assert rc == 0, f"unexpected content change in frozen feature-list file: {p}"
anchor = json.loads(subprocess.run(["git", "show", f"{ANCHOR}:{ACTIVE_PHASE_FILE}"], capture_output=True, text=True, check=True).stdout)
worktree = json.loads(Path(ACTIVE_PHASE_FILE).read_text())
for key in anchor:
    if key == "features":
        continue
    assert anchor.get(key) == worktree.get(key), f"top-level key '{key}' changed outside features array"
assert not (set(worktree) - set(anchor)), f"unexpected new top-level key(s): {set(worktree) - set(anchor)}"
anchor_by_id = {f["id"]: f for f in anchor["features"]}
worktree_by_id = {f["id"]: f for f in worktree["features"]}
assert set(anchor_by_id) == set(worktree_by_id), "feature id set changed (add/remove not permitted by this guard)"
for fid, a_feat in anchor_by_id.items():
    w_feat = worktree_by_id[fid]
    if fid == OWN_ID:
        assert a_feat == w_feat, f"feature {OWN_ID}'s own object changed before Step 7 -- not permitted by this contract"
        continue
    a_rest = {k: v for k, v in a_feat.items() if k != "status"}
    w_rest = {k: v for k, v in w_feat.items() if k != "status"}
    assert a_rest == w_rest, f"feature {fid} changed a field other than status"
print(f"PASS feature-list guard: prior-phase files byte-identical to {ANCHOR}; {ACTIVE_PHASE_FILE} deltas confined to status transitions on features other than {OWN_ID}, {OWN_ID} itself unchanged")
PY
